-- LF PE10 diagnostic experiment / inert method definitions only.
-- Migration Train exact-version source-first; no runtime bindings or activations.
CREATE TABLE programacion.pe10_method_modules (
 module_code text PRIMARY KEY,
 module_type text NOT NULL CHECK(module_type IN ('BASE','ALGORITHM')),
 name text NOT NULL,
 definition jsonb NOT NULL CHECK(jsonb_typeof(definition)='object'),
 version_code text NOT NULL DEFAULT 'PE10_METHOD_V1',
 status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','RETIRED')),
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE programacion.pe10_method_roles (
 role_code text PRIMARY KEY,
 role_name text NOT NULL,
 specialty text NOT NULL,
 role_contract jsonb NOT NULL CHECK(jsonb_typeof(role_contract)='object'),
 version_code text NOT NULL DEFAULT 'PE10_METHOD_V1',
 status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','RETIRED')),
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE programacion.pe10_method_variants (
 method_code text PRIMARY KEY,
 base_code text NOT NULL REFERENCES programacion.pe10_method_modules(module_code),
 algorithm_codes text[] NOT NULL DEFAULT ARRAY[]::text[],
 definition_version text NOT NULL DEFAULT 'PE10_METHOD_V1',
 status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','RETIRED')),
 case_ref text NOT NULL DEFAULT 'PE10-IG-M107-M109-P0',
 execution_contract jsonb NOT NULL CHECK(jsonb_typeof(execution_contract)='object'),
 created_at timestamptz NOT NULL DEFAULT now(),
 CONSTRAINT pe10_unique_combination UNIQUE(base_code,algorithm_codes),
 CONSTRAINT pe10_base_allowed CHECK(base_code IN ('A','B')),
 CONSTRAINT pe10_algorithms_allowed CHECK(algorithm_codes <@ ARRAY['D','M','C','E']::text[])
);

INSERT INTO programacion.pe10_method_modules(module_code,module_type,name,definition) VALUES ('A','BASE','Individual SRCR','{"algorithm":"SRCR root cause, hypothesis alternatives, counterchecks","runtime":"One integrated investigator"}'::jsonb);

INSERT INTO programacion.pe10_method_modules(module_code,module_type,name,definition) VALUES ('B','BASE','Five-subagent SRCR','{"runtime":"Five independently isolated producers then separate independent synthesizer","roles":["ARCHITECTURE","PERFORMANCE","AUTHORITY","COVERAGE","INNOVATION"],"synthesizer":"SYNTHESIZER","must_not_simulate":"If independent subagents cannot be run, B is NOT_EXECUTED"}'::jsonb);

INSERT INTO programacion.pe10_method_modules(module_code,module_type,name,definition) VALUES ('D','ALGORITHM','GDE BARINEL information gain','{"algos":["GDE minimal hitting sets from conflict sets","BARINEL likelihood for probabilistic intermittent failures","Expected entropy reduction for next query"],"steps":["Construct diagnosis hypotheses and test/component footprint from observed data","GDE: derive minimal hitting sets of actual conflict sets, retain open-world alternatives","BARINEL only with measurable spectra: fit component health h∈[0,1] via likelihood maximization; rank candidates with justified priors","IG(q) = H(diagnoses) - E_outcome[H(diagnoses | outcome)]; choose informative SQL with cost included","If priors/outcome probabilities not justified, transparently use ordinal discrimination/cost, not fake probabilities"],"formula":"L(d,h)=PRODUCT_pass(PRODUCT_{c in d intersect trace} h_c)*PRODUCT_fail(1-PRODUCT_{c in d intersect trace} h_c)","caveat":"Never claim BARINEL calibration without executable spectrum/test outcomes"}'::jsonb);

INSERT INTO programacion.pe10_method_modules(module_code,module_type,name,definition) VALUES ('M','ALGORITHM','ATMS assumptions and evidence','{"algo":"Assumption-Based Truth Maintenance System","steps":["For each evidence store its source, time, identity, assumptions and dependent claims","Track minimal justifications, nogoods and alternative supports","On invalidation propagate to downstream conclusions","Reuse only with observed equivalence of source, time and query meaning"],"caveat":"An ordinary note list is not equivalent to implemented dependency propagation"}'::jsonb);

INSERT INTO programacion.pe10_method_modules(module_code,module_type,name,definition) VALUES ('C','ALGORITHM','Metamorphic and invariant verification','{"algos":["TLP 3-valued TRUE/FALSE/NULL partition","Positive/negative contract-derived invariants","QED algebraic equivalence or VeriEQL SMT counterexamples if actual compatible verifier available","Invalidator-inspired overfitting checks"],"steps":["Derive applicable invariants from actual contract and schema, not known target answers","Reconcile population partitions, unknowns, absent identities, comparators and evidence provenance as applicable","Test a valid case and a counterexample where meaningful","Use solver only when installed and supported; otherwise report unproven"],"caveat":"TLP consistency of SQL engine cannot prove missing business rule"}'::jsonb);

INSERT INTO programacion.pe10_method_modules(module_code,module_type,name,definition) VALUES ('E','ALGORITHM','Evidence-governed final decision','{"states":["VERIFY_FIRST","REPAIR_REQUIRED","NEEDS_MORE_EVIDENCE","NO_ACTION_SUPPORTED"],"rules":["Choose state from observed risk, demonstrated defect and material unknowns","Specify evidence, scope, potential falsifiers and reversal criteria","No DONE/READY or implemented repair without verified execution","No known-answer target state supplied"]}'::jsonb);

INSERT INTO programacion.pe10_method_roles(role_code,role_name,specialty,role_contract) VALUES ('SRCR_SINGLE','Reparador integrado','All five lenses in one autonomous investigator','{"scope":"LF_ONLY_DIAGNOSTIC","status":"DRAFT","input":"Same exact frozen case P0, without findings or evaluation answers","rules":["Research independently via authorized read-only observations","Hypotheses must be falsifiable, including no defect","No predetermined questions, diagnosis, object names, answers or artificial SQL caps","Never read peer reports before own immutable report","All evidence tied to precise source, window, transformation, limitations","No edits, runtime changes, or simulated tools"],"output":["literal SELECT and raw readback","observed findings","unresolved unknowns","counterexamples and negative tests","causal hypothesis","minimal safe action","measured costs"],"objectives":["Competing hypotheses and independent causal analysis","Explore architecture, performance, authority, coverage, novelty","Seek disconfirming evidence rather than predetermined targets"],"critical_checks":["Reconstruct source and causal chain","Do not confuse correlation and proof"],"method_rule":"Apply only algorithm modules assigned to this method, not all algorithms at once"}'::jsonb);

INSERT INTO programacion.pe10_method_roles(role_code,role_name,specialty,role_contract) VALUES ('ARCHITECTURE','Arquitectura','Topologies, module interfaces and dependencies','{"scope":"LF_ONLY_DIAGNOSTIC","status":"DRAFT","input":"Same exact frozen case P0, without findings or evaluation answers","rules":["Research independently via authorized read-only observations","Hypotheses must be falsifiable, including no defect","No predetermined questions, diagnosis, object names, answers or artificial SQL caps","Never read peer reports before own immutable report","All evidence tied to precise source, window, transformation, limitations","No edits, runtime changes, or simulated tools"],"output":["literal SELECT and raw readback","observed findings","unresolved unknowns","counterexamples and negative tests","causal hypothesis","minimal safe action","measured costs"],"objectives":["Reconstruct topology and source-to-executor paths","Trace version and variant relations and lifecycle boundaries","Look for cross-module effects, unexpected dependency paths and alternate root causes"],"critical_checks":["Object resolution vs textual mentions","False topology from incomplete registries"],"method_rule":"Apply only algorithm modules assigned to this method, not all algorithms at once"}'::jsonb);

INSERT INTO programacion.pe10_method_roles(role_code,role_name,specialty,role_contract) VALUES ('PERFORMANCE','Rendimiento','End-to-end performance and efficiency','{"scope":"LF_ONLY_DIAGNOSTIC","status":"DRAFT","input":"Same exact frozen case P0, without findings or evaluation answers","rules":["Research independently via authorized read-only observations","Hypotheses must be falsifiable, including no defect","No predetermined questions, diagnosis, object names, answers or artificial SQL caps","Never read peer reports before own immutable report","All evidence tied to precise source, window, transformation, limitations","No edits, runtime changes, or simulated tools"],"output":["literal SELECT and raw readback","observed findings","unresolved unknowns","counterexamples and negative tests","causal hypothesis","minimal safe action","measured costs"],"objectives":["Identify time boundaries, denominators, waits, cache reuse and duplication","Compare equivalent cohorts, workflows and provenance","Quantify uncertainty and causal alternatives"],"critical_checks":["Speed claims with unmatched clocks","Unmeasured stages and confounders"],"method_rule":"Apply only algorithm modules assigned to this method, not all algorithms at once"}'::jsonb);

INSERT INTO programacion.pe10_method_roles(role_code,role_name,specialty,role_contract) VALUES ('AUTHORITY','Autoridad','Governance, provenance, permissions and identity','{"scope":"LF_ONLY_DIAGNOSTIC","status":"DRAFT","input":"Same exact frozen case P0, without findings or evaluation answers","rules":["Research independently via authorized read-only observations","Hypotheses must be falsifiable, including no defect","No predetermined questions, diagnosis, object names, answers or artificial SQL caps","Never read peer reports before own immutable report","All evidence tied to precise source, window, transformation, limitations","No edits, runtime changes, or simulated tools"],"output":["literal SELECT and raw readback","observed findings","unresolved unknowns","counterexamples and negative tests","causal hypothesis","minimal safe action","measured costs"],"objectives":["Trace the authority and source-of-truth chain","Check grants, role identities and separation of duties","Test source integrity, time validity and bypass possibilities"],"critical_checks":["Claimed permissions without readback","Current data mistaken for historical"],"method_rule":"Apply only algorithm modules assigned to this method, not all algorithms at once"}'::jsonb);

INSERT INTO programacion.pe10_method_roles(role_code,role_name,specialty,role_contract) VALUES ('COVERAGE','Cobertura','Completeness, exclusions, negative and edge conditions','{"scope":"LF_ONLY_DIAGNOSTIC","status":"DRAFT","input":"Same exact frozen case P0, without findings or evaluation answers","rules":["Research independently via authorized read-only observations","Hypotheses must be falsifiable, including no defect","No predetermined questions, diagnosis, object names, answers or artificial SQL caps","Never read peer reports before own immutable report","All evidence tied to precise source, window, transformation, limitations","No edits, runtime changes, or simulated tools"],"output":["literal SELECT and raw readback","observed findings","unresolved unknowns","counterexamples and negative tests","causal hypothesis","minimal safe action","measured costs"],"objectives":["Define observed population and its complement","Explore unseen consumers, empty sets, missing entities and boundary classes","Derive completeness checks from observed schema and contracts"],"critical_checks":["Partial inventory masquerading as totality","Lexical occurrence mistaken for proven execution"],"method_rule":"Apply only algorithm modules assigned to this method, not all algorithms at once"}'::jsonb);

INSERT INTO programacion.pe10_method_roles(role_code,role_name,specialty,role_contract) VALUES ('INNOVATION','Innovación crítica','Alternatives, second-order effects and unexpected causes','{"scope":"LF_ONLY_DIAGNOSTIC","status":"DRAFT","input":"Same exact frozen case P0, without findings or evaluation answers","rules":["Research independently via authorized read-only observations","Hypotheses must be falsifiable, including no defect","No predetermined questions, diagnosis, object names, answers or artificial SQL caps","Never read peer reports before own immutable report","All evidence tied to precise source, window, transformation, limitations","No edits, runtime changes, or simulated tools"],"output":["literal SELECT and raw readback","observed findings","unresolved unknowns","counterexamples and negative tests","causal hypothesis","minimal safe action","measured costs"],"objectives":["Generate distinct causal mechanisms and simpler explanations","Attack consensus and find neglected interactions","Design discriminatory counterchecks and optional novel avenues"],"critical_checks":["Novelty without evidence","Consensus without falsification"],"method_rule":"Apply only algorithm modules assigned to this method, not all algorithms at once"}'::jsonb);

INSERT INTO programacion.pe10_method_roles(role_code,role_name,specialty,role_contract) VALUES ('SYNTHESIZER','Sintetizador independiente','Reconcile five independently frozen reports','{"scope":"LF_ONLY_DIAGNOSTIC","status":"DRAFT","input":"Same exact frozen case P0, without findings or evaluation answers","rules":["Research independently via authorized read-only observations","Hypotheses must be falsifiable, including no defect","No predetermined questions, diagnosis, object names, answers or artificial SQL caps","Never read peer reports before own immutable report","All evidence tied to precise source, window, transformation, limitations","No edits, runtime changes, or simulated tools"],"output":["literal SELECT and raw readback","observed findings","unresolved unknowns","counterexamples and negative tests","causal hypothesis","minimal safe action","measured costs"],"objectives":["Require separately frozen originals","Reconcile contradictions by authority and readbacks, not voting","Preserve disagreements, uncertainty and counterevidence","Deliver coherent diagnostic and least risky next action"],"critical_checks":["Cannot rewrite individual findings","Cannot equate five lenses in one chat with independent agents"],"method_rule":"Apply only algorithm modules assigned to this method, not all algorithms at once"}'::jsonb);

