ALTER TABLE programacion.pe10_method_modules ENABLE ROW LEVEL SECURITY;
ALTER TABLE programacion.pe10_method_roles ENABLE ROW LEVEL SECURITY;
ALTER TABLE programacion.pe10_method_variants ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE programacion.pe10_method_modules,programacion.pe10_method_roles,programacion.pe10_method_variants FROM PUBLIC;
DO $permissions$
BEGIN
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='supabase_read_only_user') THEN
   GRANT SELECT ON programacion.pe10_method_modules,programacion.pe10_method_roles,programacion.pe10_method_variants TO supabase_read_only_user;
   EXECUTE 'CREATE POLICY pe10_method_modules_ro ON programacion.pe10_method_modules FOR SELECT TO supabase_read_only_user USING(true)';
   EXECUTE 'CREATE POLICY pe10_method_roles_ro ON programacion.pe10_method_roles FOR SELECT TO supabase_read_only_user USING(true)';
   EXECUTE 'CREATE POLICY pe10_method_variants_ro ON programacion.pe10_method_variants FOR SELECT TO supabase_read_only_user USING(true)';
 END IF;
END;
$permissions$;
DO $integrity$
DECLARE nmods integer; nroles integer; nvariants integer; nuniq integer; nbroken integer;
BEGIN
 SELECT count(*) INTO nmods FROM programacion.pe10_method_modules;
 SELECT count(*) INTO nroles FROM programacion.pe10_method_roles;
 SELECT count(*),count(DISTINCT (base_code,algorithm_codes)) INTO nvariants,nuniq FROM programacion.pe10_method_variants;
 SELECT count(*) INTO nbroken FROM programacion.pe10_method_variants v WHERE EXISTS
 (SELECT 1 FROM unnest(v.algorithm_codes) a WHERE NOT EXISTS(SELECT 1 FROM programacion.pe10_method_modules m WHERE m.module_code=a AND m.module_type='ALGORITHM'));
 IF nmods<>6 OR nroles<>7 OR nvariants<>32 OR nuniq<>32 OR nbroken<>0 THEN
   RAISE EXCEPTION 'PE10_CATALOG_INVALID modules=% roles=% methods=% distinct=% broken=%',nmods,nroles,nvariants,nuniq,nbroken;
 END IF;
 IF EXISTS(SELECT 1 FROM programacion.pe10_method_variants WHERE status<>'DRAFT') THEN RAISE EXCEPTION 'PE10_METHOD_UNEXPECTED_ACTIVATION'; END IF;
END;
$integrity$;